function commercial_can_view(array $user):bool{return (bool)$user['is_active']&&email_access_allowed($user);}
function commercial_can_manage(array $user):bool{return commercial_can_view($user)&&in_array($user['role'],['OWNER_ADMIN','ADMIN','OPS_MANAGER','SUPERVISOR'],true);}
function commercial_text(array $input,string $key,int $max=5000,bool $required=false):string{$value=trim((string)($input[$key]??''));if($required&&$value==='')throw new DomainException(ucwords(str_replace('_',' ',$key)).' is required.',422);if(mb_strlen($value)>$max)throw new DomainException(ucwords(str_replace('_',' ',$key)).' is too long.',422);return $value;}
function commercial_money(mixed $value):float{$number=filter_var($value,FILTER_VALIDATE_FLOAT);if($number===false||$number<0)throw new DomainException('Amounts must be valid positive numbers.',422);return round((float)$number,2);}
function commercial_profile(array $user):array{return rows('SELECT * FROM commercial_profiles WHERE organization_id=?',[$user['owner_id']])[0]??['organization_id'=>$user['owner_id'],'legal_name'=>$user['company_name'],'trading_name'=>'','registered_address'=>'','email'=>$user['email'],'phone'=>'','website'=>'','tin'=>'','rc_number'=>'','default_currency'=>'NGN','default_vat'=>'7.500','default_payment_terms'=>'','quotation_terms'=>'','invoice_terms'=>'','authorized_signatory'=>'','quote_prefix'=>'QT','invoice_prefix'=>'INV'];}
function commercial_profile_save(array $user,array $input):void{if(!commercial_can_manage($user))throw new DomainException('You cannot manage Commercial settings.',403);$currency=strtoupper(commercial_text($input,'default_currency',3,true));if(!preg_match('/^[A-Z]{3}$/',$currency))throw new DomainException('Use a three-letter default currency.',422);$vat=min(100,commercial_money($input['default_vat']??0));$values=[commercial_text($input,'legal_name',255,true),commercial_text($input,'trading_name',255),commercial_text($input,'registered_address'),commercial_text($input,'email',255),commercial_text($input,'phone',50),commercial_text($input,'website',255),commercial_text($input,'tin',100),commercial_text($input,'rc_number',100),$currency,$vat,commercial_text($input,'default_payment_terms',255),commercial_text($input,'quotation_terms'),commercial_text($input,'invoice_terms'),commercial_text($input,'authorized_signatory',255),strtoupper(commercial_text($input,'quote_prefix',20,true)),strtoupper(commercial_text($input,'invoice_prefix',20,true))];db()->prepare('INSERT INTO commercial_profiles(organization_id,legal_name,trading_name,registered_address,email,phone,website,tin,rc_number,default_currency,default_vat,default_payment_terms,quotation_terms,invoice_terms,authorized_signatory,quote_prefix,invoice_prefix,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE legal_name=VALUES(legal_name),trading_name=VALUES(trading_name),registered_address=VALUES(registered_address),email=VALUES(email),phone=VALUES(phone),website=VALUES(website),tin=VALUES(tin),rc_number=VALUES(rc_number),default_currency=VALUES(default_currency),default_vat=VALUES(default_vat),default_payment_terms=VALUES(default_payment_terms),quotation_terms=VALUES(quotation_terms),invoice_terms=VALUES(invoice_terms),authorized_signatory=VALUES(authorized_signatory),quote_prefix=VALUES(quote_prefix),invoice_prefix=VALUES(invoice_prefix),updated_by=VALUES(updated_by)')->execute([$user['owner_id'],...$values,$user['id']]);operation_audit($user,'commercial.profile.updated','commercial_profile',$user['owner_id'],null,['legal_name'=>$values[0]]);}
function commercial_customer(array $user,string $id):array{$row=rows('SELECT * FROM commercial_customers WHERE id=? AND organization_id=?',[$id,$user['owner_id']])[0]??null;if(!$row)throw new DomainException('Customer not found.',404);return $row;}
function commercial_customer_save(array $user,array $input):string{if(!commercial_can_manage($user))throw new DomainException('You cannot manage customers.',403);$id=commercial_text($input,'id',36)?:uuid();$existing=rows('SELECT * FROM commercial_customers WHERE id=? AND organization_id=?',[$id,$user['owner_id']])[0]??null;$currency=strtoupper(commercial_text($input,'currency',3)?:'NGN');$values=[commercial_text($input,'name',255,true),commercial_text($input,'customer_code',100)?:null,commercial_text($input,'rc_number',100),commercial_text($input,'industry',150),commercial_text($input,'website',255),commercial_text($input,'primary_contact',255),commercial_text($input,'finance_contact',255),commercial_text($input,'procurement_contact',255),commercial_text($input,'email',255),commercial_text($input,'phone',50),commercial_text($input,'billing_address'),commercial_text($input,'service_address'),commercial_text($input,'state_region',150),commercial_text($input,'country',100),$currency,commercial_text($input,'payment_terms',255),(int)($input['credit_period']??0)?:null,commercial_text($input,'notes'),commercial_text($input,'tin',100),commercial_text($input,'tax_registered_name',255),commercial_text($input,'tax_registered_address'),commercial_text($input,'tax_jurisdiction',150),commercial_text($input,'tax_authority',150)];if($existing){db()->prepare('UPDATE commercial_customers SET name=?,customer_code=?,rc_number=?,industry=?,website=?,primary_contact=?,finance_contact=?,procurement_contact=?,email=?,phone=?,billing_address=?,service_address=?,state_region=?,country=?,currency=?,payment_terms=?,credit_period=?,notes=?,tin=?,tax_registered_name=?,tax_registered_address=?,tax_jurisdiction=?,tax_authority=? WHERE id=? AND organization_id=?')->execute([...$values,$id,$user['owner_id']]);}else{db()->prepare('INSERT INTO commercial_customers(id,organization_id,name,customer_code,rc_number,industry,website,primary_contact,finance_contact,procurement_contact,email,phone,billing_address,service_address,state_region,country,currency,payment_terms,credit_period,notes,tin,tax_registered_name,tax_registered_address,tax_jurisdiction,tax_authority,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$user['owner_id'],...$values,$user['id']]);}operation_audit($user,$existing?'commercial.customer.updated':'commercial.customer.created','commercial_customer',$id,$existing,['name'=>$values[0],'tin'=>$values[18]]);return $id;}
function commercial_bank_save(array $user,array $input):string{if(!commercial_can_manage($user))throw new DomainException('You cannot manage bank accounts.',403);$id=uuid();$currency=strtoupper(commercial_text($input,'currency',3,true));if(!empty($input['is_default']))db()->prepare('UPDATE commercial_bank_accounts SET is_default=0 WHERE organization_id=? AND currency=?')->execute([$user['owner_id'],$currency]);db()->prepare('INSERT INTO commercial_bank_accounts(id,organization_id,account_name,bank_name,account_number,currency,swift_code,instructions,is_default) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$id,$user['owner_id'],commercial_text($input,'account_name',255,true),commercial_text($input,'bank_name',255,true),commercial_text($input,'account_number',100,true),$currency,commercial_text($input,'swift_code',50),commercial_text($input,'instructions'),!empty($input['is_default'])]);operation_audit($user,'commercial.bank.created','commercial_bank_account',$id,null,['currency'=>$currency]);return $id;}
function commercial_brand_file(array $file,string $label):array{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return [null,null];if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>5*1024*1024)throw new DomainException($label.' must be a JPEG or PNG up to 5 MB.',422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png'],true))throw new DomainException($label.' must be a JPEG or PNG.',422);return [$mime,file_get_contents((string)$file['tmp_name'])];}
function commercial_brand_values(mixed $values):array{$result=[];foreach((array)$values as $value){$value=trim((string)$value);if($value!==''&&!in_array($value,$result,true))$result[]=mb_substr($value,0,500);}return array_slice($result,0,10);}
function commercial_brand_save(array $user,array $input,array $files):string{if(!commercial_can_manage($user))throw new DomainException('You cannot manage Commercial branding.',403);$mode=in_array($input['creation_mode']??'',['ELEMENTS','ARTWORK'],true)?$input['creation_mode']:'ELEMENTS';$id=commercial_text($input,'id',36)?:uuid();$existing=rows('SELECT * FROM commercial_brands WHERE id=? AND organization_id=?',[$id,$user['owner_id']])[0]??null;[$logoMime,$logoData]=commercial_brand_file($files['logo']??[],'Logo');[$headerMime,$headerData]=commercial_brand_file($files['header_artwork']??[],'Header artwork');[$footerMime,$footerData]=commercial_brand_file($files['footer_artwork']??[],'Footer artwork');if($mode==='ARTWORK'&&!$existing&&!$headerData)throw new DomainException('Upload header artwork for an artwork-based brand.',422);$brandName=commercial_text($input,'brand_name',255,true);$companyName=commercial_text($input,'company_name',255,true);$addresses=commercial_brand_values($input['addresses']??[]);$phones=commercial_brand_values($input['phones']??[]);$emails=commercial_brand_values($input['emails']??[]);$website=commercial_text($input,'website',255);$default=!empty($input['is_default']);if($default)db()->prepare('UPDATE commercial_brands SET is_default=0 WHERE organization_id=?')->execute([$user['owner_id']]);if($existing){db()->prepare('UPDATE commercial_brands SET brand_name=?,company_name=?,creation_mode=?,addresses=?,phones=?,emails=?,website=?,logo_mime=COALESCE(?,logo_mime),logo_data=COALESCE(?,logo_data),header_mime=COALESCE(?,header_mime),header_data=COALESCE(?,header_data),footer_mime=COALESCE(?,footer_mime),footer_data=COALESCE(?,footer_data),is_default=? WHERE id=? AND organization_id=?')->execute([$brandName,$companyName,$mode,json_encode($addresses),json_encode($phones),json_encode($emails),$website,$logoMime,$logoData,$headerMime,$headerData,$footerMime,$footerData,$default,$id,$user['owner_id']]);}else{db()->prepare('INSERT INTO commercial_brands(id,organization_id,brand_name,company_name,creation_mode,addresses,phones,emails,website,logo_mime,logo_data,header_mime,header_data,footer_mime,footer_data,is_default,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$user['owner_id'],$brandName,$companyName,$mode,json_encode($addresses),json_encode($phones),json_encode($emails),$website,$logoMime,$logoData,$headerMime,$headerData,$footerMime,$footerData,$default,$user['id']]);}operation_audit($user,$existing?'commercial.brand.updated':'commercial.brand.created','commercial_brand',$id,$existing,['brand_name'=>$brandName,'creation_mode'=>$mode]);return $id;}
function commercial_document_brand_set(array $user,string $documentId,string $brandId):void{if($brandId===''){db()->prepare('UPDATE commercial_documents SET brand_id=NULL WHERE id=? AND organization_id=?')->execute([$documentId,$user['owner_id']]);return;}if(!rows('SELECT 1 FROM commercial_brands WHERE id=? AND organization_id=?',[$brandId,$user['owner_id']]))throw new DomainException('Choose a valid saved brand.',422);db()->prepare('UPDATE commercial_documents SET brand_id=? WHERE id=? AND organization_id=?')->execute([$brandId,$documentId,$user['owner_id']]);}
function commercial_document_signatory_set(array $user,string $documentId,array $input,array $files):void{[$mime,$data]=commercial_brand_file($files['signature']??[],'Signature');$name=commercial_text($input,'signatory_name',255);$title=commercial_text($input,'signatory_title',255);db()->prepare('UPDATE commercial_documents SET signatory_name=?,signatory_title=?,signature_mime=COALESCE(?,signature_mime),signature_data=COALESCE(?,signature_data) WHERE id=? AND organization_id=?')->execute([$name?:null,$title?:null,$mime,$data,$documentId,$user['owner_id']]);}
function commercial_document_adjustments_set(array $user,string $documentId,array $input):void{$document=commercial_document($user,$documentId,true);$subtotal=(float)$document['subtotal'];$discountRate=max(0,min(100,(float)($input['document_discount_rate']??0)));$taxRate=max(0,min(100,(float)($input['document_tax_rate']??0)));$discount=round($subtotal*$discountRate/100,2);$tax=round(($subtotal-$discount)*$taxRate/100,2);$total=round($subtotal-$discount+$tax+(float)$document['adjustment_total'],2);db()->prepare('UPDATE commercial_documents SET discount_total=?,tax_total=?,grand_total=? WHERE id=? AND organization_id=?')->execute([$discount,$tax,$total,$documentId,$user['owner_id']]);}
function commercial_brand_snapshot(array $user,?string $id):?array{if(!$id)return null;$brand=rows('SELECT * FROM commercial_brands WHERE id=? AND organization_id=?',[$id,$user['owner_id']])[0]??null;if(!$brand)return null;foreach(['logo','header','footer'] as $asset){$data=$brand[$asset.'_data']??null;$brand[$asset.'_data']=$data?base64_encode($data):null;}return $brand;}
function commercial_document(array $user,string $id,bool $lock=false):array{$row=rows('SELECT d.*,c.name customer_name,c.billing_address customer_address,c.email customer_email,c.phone customer_phone,c.tin customer_tin FROM commercial_documents d JOIN commercial_customers c ON c.id=d.customer_id WHERE d.id=? AND d.organization_id=?'.($lock?' FOR UPDATE':''),[$id,$user['owner_id']])[0]??null;if(!$row)throw new DomainException('Commercial document not found.',404);$row['items']=rows('SELECT * FROM commercial_line_items WHERE document_id=? ORDER BY sort_order,id',[$id]);return $row;}
function commercial_next_number(array $user,string $type):string{$profile=commercial_profile($user);if(empty($profile['updated_by']))commercial_profile_save($user,$profile);$profile=rows('SELECT * FROM commercial_profiles WHERE organization_id=? FOR UPDATE',[$user['owner_id']])[0];$field=$type==='QUOTATION'?'next_quote_number':'next_invoice_number';$prefix=$type==='QUOTATION'?$profile['quote_prefix']:$profile['invoice_prefix'];$number=(int)$profile[$field];db()->prepare("UPDATE commercial_profiles SET {$field}={$field}+1 WHERE organization_id=?")->execute([$user['owner_id']]);return $prefix.'-'.gmdate('Y').'-'.str_pad((string)$number,4,'0',STR_PAD_LEFT);}
function commercial_items(array $input):array{$descriptions=$input['item_description']??[];$items=[];foreach($descriptions as $i=>$description){$description=trim((string)$description);if($description==='')continue;$quantity=commercial_money($input['item_quantity'][$i]??1);$duration=commercial_money($input['item_duration'][$i]??1);$rate=commercial_money($input['item_rate'][$i]??0);$discount=min(100,commercial_money($input['item_discount'][$i]??0));$tax=min(100,commercial_money($input['item_tax'][$i]??0));$base=round($quantity*$duration*$rate,2);$discountAmount=round($base*$discount/100,2);$taxAmount=round(($base-$discountAmount)*$tax/100,2);$items[]=['description'=>mb_substr($description,0,5000),'quantity'=>$quantity,'unit'=>mb_substr(trim((string)($input['item_unit'][$i]??'Each')),0,40),'duration'=>$duration,'rate'=>$rate,'discount_rate'=>$discount,'tax_rate'=>$tax,'base_amount'=>$base,'discount_amount'=>$discountAmount,'tax_amount'=>$taxAmount,'total_amount'=>round($base-$discountAmount+$taxAmount,2)];}if(!$items)throw new DomainException('Add at least one line item.',422);return $items;}
function commercial_document_save(array $user,array $input,string $type):string{if(!commercial_can_manage($user))throw new DomainException('You cannot create commercial documents.',403);if(!in_array($type,['QUOTATION','INVOICE'],true))throw new DomainException('Invalid document type.',422);$customer=commercial_customer($user,commercial_text($input,'customer_id',36,true));$items=commercial_items($input);$id=commercial_text($input,'id',36);$existing=$id?commercial_document($user,$id,true):null;if($existing&&$existing['status']!=='DRAFT')throw new DomainException('Issued documents cannot be edited.',409);$subtotal=array_sum(array_column($items,'base_amount'));$discount=array_sum(array_column($items,'discount_amount'));$tax=array_sum(array_column($items,'tax_amount'));$adjustment=(float)($input['adjustment_total']??0);$total=round($subtotal-$discount+$tax+$adjustment,2);$currency=strtoupper(commercial_text($input,'currency',3,true));$issue=commercial_text($input,'issue_date',10,true);$valid=$type==='QUOTATION'?commercial_text($input,'valid_until',10):'';$due=$type==='INVOICE'?commercial_text($input,'due_date',10):'';if($type==='QUOTATION'&&$valid!==''&&$valid<$issue)throw new DomainException('Valid-until date cannot precede the issue date.',422);if($type==='INVOICE'&&$due!==''&&$due<$issue)throw new DomainException('Due date cannot precede the invoice date.',422);$pdo=db();if(!$pdo->inTransaction())$pdo->beginTransaction();try{if(!$existing){$id=uuid();$number=commercial_next_number($user,$type);db()->prepare('INSERT INTO commercial_documents(id,organization_id,customer_id,document_type,document_number,issue_date,valid_until,due_date,currency,customer_po,customer_reference,rfq_number,prepared_by,bank_account_id,payment_terms,delivery_terms,lead_time,notes,subtotal,discount_total,tax_total,adjustment_total,grand_total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$user['owner_id'],$customer['id'],$type,$number,$issue,$valid?:null,$due?:null,$currency,commercial_text($input,'customer_po',150),commercial_text($input,'customer_reference',150),commercial_text($input,'rfq_number',150),$user['id'],commercial_text($input,'bank_account_id',36)?:null,commercial_text($input,'payment_terms'),commercial_text($input,'delivery_terms'),commercial_text($input,'lead_time',255),commercial_text($input,'notes'),$subtotal,$discount,$tax,$adjustment,$total]);}else{db()->prepare('UPDATE commercial_documents SET customer_id=?,issue_date=?,valid_until=?,due_date=?,currency=?,customer_po=?,customer_reference=?,rfq_number=?,bank_account_id=?,payment_terms=?,delivery_terms=?,lead_time=?,notes=?,subtotal=?,discount_total=?,tax_total=?,adjustment_total=?,grand_total=? WHERE id=?')->execute([$customer['id'],$issue,$valid?:null,$due?:null,$currency,commercial_text($input,'customer_po',150),commercial_text($input,'customer_reference',150),commercial_text($input,'rfq_number',150),commercial_text($input,'bank_account_id',36)?:null,commercial_text($input,'payment_terms'),commercial_text($input,'delivery_terms'),commercial_text($input,'lead_time',255),commercial_text($input,'notes'),$subtotal,$discount,$tax,$adjustment,$total,$id]);db()->prepare('DELETE FROM commercial_line_items WHERE document_id=?')->execute([$id]);} $stmt=db()->prepare('INSERT INTO commercial_line_items(id,document_id,description,quantity,unit,duration,rate,discount_rate,tax_rate,base_amount,discount_amount,tax_amount,total_amount,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($items as $i=>$item)$stmt->execute([uuid(),$id,$item['description'],$item['quantity'],$item['unit'],$item['duration'],$item['rate'],$item['discount_rate'],$item['tax_rate'],$item['base_amount'],$item['discount_amount'],$item['tax_amount'],$item['total_amount'],$i]);db()->prepare('INSERT INTO commercial_document_events(document_id,actor_user_id,event_type,new_value) VALUES(?,?,?,?)')->execute([$id,$user['id'],$existing?'DRAFT_UPDATED':'CREATED',json_encode(['total'=>$total],JSON_THROW_ON_ERROR)]);operation_audit($user,$existing?'commercial.document.updated':'commercial.document.created',strtolower($type),$id,$existing,['total'=>$total]);if($pdo->inTransaction())$pdo->commit();return $id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function commercial_snapshot(array $user,string $id):array{$document=commercial_document($user,$id);if(!empty($document['signature_data']))$document['signature_data']=base64_encode($document['signature_data']);$profile=commercial_profile($user);$bank=$document['bank_account_id']?rows('SELECT * FROM commercial_bank_accounts WHERE id=? AND organization_id=?',[$document['bank_account_id'],$user['owner_id']])[0]??null:null;$brand=commercial_brand_snapshot($user,$document['brand_id']??null);if($brand&&$brand['creation_mode']==='ELEMENTS'){$profile['legal_name']=$brand['company_name'];$profile['registered_address']=implode("\n",(array)json_decode((string)$brand['addresses'],true));$profile['phone']=implode(' · ',(array)json_decode((string)$brand['phones'],true));$profile['email']=implode(' · ',(array)json_decode((string)$brand['emails'],true));$profile['website']=$brand['website'];}return ['document'=>$document,'issuer'=>$profile,'bank'=>$bank,'brand'=>$brand,'captured_at'=>gmdate('c')];}
function commercial_issue(array $user,string $id):void{if(!commercial_can_manage($user))throw new DomainException('You cannot issue documents.',403);$document=commercial_document($user,$id,true);if($document['status']!=='DRAFT')throw new DomainException('Only drafts can be issued.',409);$snapshot=commercial_snapshot($user,$id);db()->prepare("UPDATE commercial_documents SET status='ISSUED',issued_snapshot=?,issued_at=UTC_TIMESTAMP() WHERE id=?")->execute([json_encode($snapshot,JSON_THROW_ON_ERROR),$id]);db()->prepare("INSERT INTO commercial_document_events(document_id,actor_user_id,event_type,new_value) VALUES(?,?,'ISSUED',?)")->execute([$id,$user['id'],json_encode(['number'=>$document['document_number']],JSON_THROW_ON_ERROR)]);operation_audit($user,'commercial.document.issued',strtolower($document['document_type']),$id,null,['number'=>$document['document_number'],'total'=>$document['grand_total']]);}
function commercial_convert_quote(array $user,string $id):string{$quote=commercial_document($user,$id,true);if($quote['document_type']!=='QUOTATION'||!in_array($quote['status'],['ISSUED','ACCEPTED'],true))throw new DomainException('Issue or accept the quotation before converting it.',409);$existing=rows("SELECT id FROM commercial_documents WHERE converted_from_id=? AND document_type='INVOICE'",[$id])[0]['id']??null;if($existing)return $existing;$pdo=db();$pdo->beginTransaction();try{$invoice=uuid();$number=commercial_next_number($user,'INVOICE');db()->prepare("INSERT INTO commercial_documents(id,organization_id,customer_id,document_type,document_number,status,issue_date,due_date,currency,customer_po,customer_reference,rfq_number,prepared_by,converted_from_id,bank_account_id,payment_terms,delivery_terms,lead_time,notes,subtotal,discount_total,tax_total,adjustment_total,grand_total) SELECT ?,organization_id,customer_id,'INVOICE',?,'DRAFT',UTC_DATE(),DATE_ADD(UTC_DATE(),INTERVAL 30 DAY),currency,customer_po,customer_reference,rfq_number,?,id,bank_account_id,payment_terms,delivery_terms,lead_time,notes,subtotal,discount_total,tax_total,adjustment_total,grand_total FROM commercial_documents WHERE id=?")->execute([$invoice,$number,$user['id'],$id]);db()->prepare('INSERT INTO commercial_line_items(id,document_id,description,quantity,unit,duration,rate,discount_rate,tax_rate,base_amount,discount_amount,tax_amount,total_amount,source_type,source_id,source_snapshot,sort_order) SELECT UUID(),?,description,quantity,unit,duration,rate,discount_rate,tax_rate,base_amount,discount_amount,tax_amount,total_amount,source_type,source_id,source_snapshot,sort_order FROM commercial_line_items WHERE document_id=?')->execute([$invoice,$id]);db()->prepare("UPDATE commercial_documents SET status='CONVERTED' WHERE id=?")->execute([$id]);db()->prepare("INSERT INTO commercial_document_events(document_id,actor_user_id,event_type,new_value) VALUES(?,?,'CONVERTED',?)")->execute([$id,$user['id'],json_encode(['invoice_id'=>$invoice],JSON_THROW_ON_ERROR)]);$pdo->commit();operation_audit($user,'commercial.quote.converted','quotation',$id,null,['invoice_id'=>$invoice]);return $invoice;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function commercial_pdf(array $data):string{$document=$data['document'];$issuer=$data['issuer'];$items=$document['items']??[];$lines=[strtoupper((string)$document['document_type']),(string)$document['document_number'],'','FROM: '.($issuer['legal_name']??$issuer['company_name']??''),str_replace(["\r","\n"],' ',(string)($issuer['registered_address']??'')),'TIN: '.($issuer['tin']??''),'','BILL TO: '.($document['customer_name']??''),str_replace(["\r","\n"],' ',(string)($document['customer_address']??'')),'Customer PO: '.($document['customer_po']??''),'Issue date: '.($document['issue_date']??''),'Due / valid: '.($document['due_date']??$document['valid_until']??''),''];foreach($items as $item)$lines[]=mb_substr((string)$item['description'],0,54).' | '.$item['quantity'].' '.$item['unit'].' x '.$item['duration'].' @ '.number_format((float)$item['rate'],2).' = '.number_format((float)$item['total_amount'],2);array_push($lines,'','Subtotal: '.number_format((float)$document['subtotal'],2),'Discount: '.number_format((float)$document['discount_total'],2),'Tax: '.number_format((float)$document['tax_total'],2),'TOTAL: '.$document['currency'].' '.number_format((float)$document['grand_total'],2),'','Payment terms: '.str_replace(["\r","\n"],' ',(string)($document['payment_terms']??'')),'Bank: '.(($data['bank']['bank_name']??'').' '.($data['bank']['account_number']??'')),'Notes: '.str_replace(["\r","\n"],' ',(string)($document['notes']??'')));$escape=static fn(string $s):string=>str_replace(['\\','(',')'],['\\\\','\(','\)'],iconv('UTF-8','Windows-1252//TRANSLIT',$s)?:'');$stream="BT\n/F1 11 Tf\n50 790 Td\n";foreach($lines as $index=>$line){if($index)$stream.="0 -19 Td\n";$stream.='('.$escape($line).") Tj\n";}$stream.="ET";$objects=["<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>","<< /Length ".strlen($stream)." >>\nstream\n{$stream}\nendstream"];$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $i=>$object){$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n{$object}\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";for($i=1;$i<=5;$i++)$pdf.=str_pad((string)$offsets[$i],10,'0',STR_PAD_LEFT)." 00000 n \n";return $pdf."trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n{$xref}\n%%EOF";}
function commercial_tax_sync(array $user,string $id):void{$document=commercial_document($user,$id);if($document['document_type']!=='INVOICE')return;$rate=(float)(commercial_profile($user)['default_vat']??0);db()->prepare("INSERT INTO commercial_tax_records(id,invoice_id,vat_rate,vat_amount,customer_tin) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE vat_rate=VALUES(vat_rate),vat_amount=VALUES(vat_amount),customer_tin=VALUES(customer_tin)")->execute([uuid(),$id,$rate,$document['tax_total'],$document['customer_tin']]);}
